/* popovers */
var OPEN=null;
function pop(b,p,on){if(on===undefined)on=!p.classList.contains("on");closePops();if(on){p.classList.add("on");if(b)b.setAttribute("aria-expanded","true");OPEN={b:b,p:p};var f=p.querySelector(".mi:not(.hide),input");if(f)setTimeout(function(){f.focus()},20)}}
function closePops(ret){if(!OPEN)return;OPEN.p.classList.remove("on");if(OPEN.b){OPEN.b.setAttribute("aria-expanded","false");if(ret)OPEN.b.focus()}OPEN=null}
document.addEventListener("click",function(e){if(OPEN&&!OPEN.p.contains(e.target)&&!(OPEN.b&&OPEN.b.contains(e.target)))closePops()});

/* views */
function view(which){show("input",which==="input");show("load",which==="load");show("view",which==="view");show("foot",which==="view");$("shBtn").disabled=which!=="view";show("crNow",which==="view");show("crSl",which==="view")}
function showInput(msg,keep){
  S.tok++;S.d=null;S.st=[];view("input");document.title="FirstRun: Replay a run";
  var e=$("err");e.textContent="";if(msg){e.appendChild(ic("bad","s-bad"));e.appendChild(document.createTextNode(msg))}e.classList.toggle("hide",!msg);
  if(!keep)$("code").value="";
  if(location.hash||location.search)history.replaceState(null,"",location.pathname);
  markExamples();
}
function openRun(d,code,ex,opt){
  opt=opt||{};S.d=d;S.code=code;S.ex=ex||"";S.i=0;S.runPlayed=false;S.tok++;teardownSpy();
  render(d);view("view");fillShare();
  setMode(opt.view==="report"?"report":"walk",true);
  var idx=0,stepId=opt.step||(!opt.stage&&DEEP?DEEP:0);
  for(var i=0;i<S.st.length;i++)if(S.st[i].id===(opt.stage||(stepId?"run":"")))idx=i;
  if(stepId){S.runPlayed=true;finishRun()}
  window.scrollTo(0,0);go(idx,false);
  if(S.mode==="report"&&idx)setTimeout(function(){S.st[idx].sec.scrollIntoView({block:"start"})},40);
  else if(idx)setTimeout(function(){window.scrollTo(0,Math.max(0,stagesTop()))},40);
  if(stepId){var r=ROWS.find(function(x){return String(x.id)===String(stepId)});if(r)setTimeout(function(){focusStep(r,true)},60);if(G&&G.stepAt[String(stepId)]!=null)gSelect(G.stepAt[String(stepId)],false)}
  markExamples();
}
function parseHash(){
  var h=location.hash.replace(/^#/,""),o={};if(!h)return o;
  var m=/^r=([^&]*)/.exec(h);if(m)o.r=m[1];
  var e=/^ex=([a-z0-9_-]+)/.exec(h);if(e)o.ex=e[1];
  h.split("&").slice(1).forEach(function(kv){var p=kv.split("=");if(p[0]==="stage")o.stage=p[1];if(p[0]==="view")o.view=p[1];if(p[0]==="step")o.step=p[1]});
  return o;
}
var CACHE={};
function fetchEx(name){if(CACHE[name])return Promise.resolve(CACHE[name]);return fetch((/^\d{8}-/.test(name)?"runs/":"examples/")+name+".txt").then(function(r){if(r.ok)return r.text();return fetch((/^\d{8}-/.test(name)?"examples/":"runs/")+name+".txt").then(function(r2){if(!r2.ok)throw 0;return r2.text()})}).then(function(t){t=t.trim();var k=t.indexOf("#r=");var c=clean(k>=0?t.slice(k+3):t);if(!c||/^</.test(c))throw 0;CACHE[name]=c;return c})}
function fromHash(){
  var o=parseHash();
  if(S.d&&((o.ex&&o.ex===S.ex)||(o.r&&!S.ex&&clean(o.r)===S.code))){if((o.view==="report")!==(S.mode==="report"))setMode(o.view==="report"?"report":"walk");if(o.stage)go2(o.stage);return}
  if(o.r){view("load");decode(o.r).then(function(d){openRun(d,clean(o.r),"",o)},function(e){showInput(e.message,true);$("code").value=o.r})}
  else if(o.ex){view("load");fetchEx(o.ex).then(function(c){return decode(c).then(function(d){openRun(d,c,o.ex,o)})}).catch(function(){showInput("That example is not available yet.")})}
  else showInput("");
}
window.addEventListener("hashchange",fromHash);

/* examples */
function exIcon(st){return st==="verified"||st==="passed"?ic("ok","s-ok"):st==="failed"?ic("bad","s-bad"):ic("warn","s-warn")}
function openEx(name){closePops();if(location.search)history.replaceState(null,"",location.pathname+location.hash);DEEP=0;location.hash="ex="+name}
function buildExamples(list){
  var X=$("exList"),Gl=$("galL");X.textContent="";Gl.textContent="";
  list.forEach(function(r){
    var b=el("button","mi");b.type="button";b.setAttribute("role","menuitem");b.dataset.ex=r.example;b.appendChild(exIcon(r.status));
    var t=el("span","mt");t.appendChild(document.createTextNode(r.title||r.name||r.example));t.appendChild(el("small",null,safeUrl(r.url)?host(r.url):"Local fixture"));b.appendChild(t);
    if(r.fixes!=null)b.appendChild(el("span","k",plural(+r.fixes,"fix","fixes")));
    b.addEventListener("click",function(){openEx(r.example)});X.appendChild(b);
    var li=el("li"),g=el("button");g.type="button";g.appendChild(exIcon(r.status));g.appendChild(el("span","gt",r.title||r.name||r.example));g.appendChild(el("span","gm",(safeUrl(r.url)?host(r.url):"local fixture")+" · "+plural(+r.fixes||0,"fix","fixes")));if(r.summary)g.appendChild(el("span","gs",r.summary));
    g.addEventListener("click",function(){openEx(r.example)});li.appendChild(g);Gl.appendChild(li);
  });
  show("gal",list.length>0);markExamples();
}
function markExamples(){var bs=$("exList").querySelectorAll(".mi");for(var i=0;i<bs.length;i++)bs[i].setAttribute("aria-current",S.d&&S.ex&&bs[i].dataset.ex===S.ex?"true":"false")}
var ORDER=["dbt","dagster","entire","accuknox","mkdocs","fixture"];
fetch("examples/index.json").then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(j){
  var runs=(j&&Array.isArray(j.runs)?j.runs:[]).filter(function(r){return r&&/^[a-z0-9_-]+$/.test(r.example||"")});
  runs.sort(function(a,b){var x=ORDER.indexOf(a.example),y=ORDER.indexOf(b.example);return (x<0?99:x)-(y<0?99:y)});buildExamples(runs);
  runs.forEach(function(r){if(r.summary)SUM[r.example]=String(r.summary)});if(S.d)renderVerdict(S.d);
}).catch(function(){buildExamples([{example:"dbt",title:"dbt Core with DuckDB",status:"verified"},{example:"dagster",title:"Dagster quickstart",status:"verified"},{example:"fixture",title:"Known-broken test fixture",status:"verified"}])});

/* wiring */
$("dec").addEventListener("click",function(){
  var raw=$("code").value;
  decode(raw).then(function(d){var c=clean(raw);history.replaceState(null,"",location.pathname+"#r="+c);DEEP=0;openRun(d,c,"",{})},function(e){var x=$("err");x.textContent="";x.appendChild(ic("bad","s-bad"));x.appendChild(document.createTextNode(e.message));x.classList.remove("hide")});
});
$("code").addEventListener("keydown",function(e){if(e.key==="Enter"&&(e.ctrlKey||e.metaKey)){e.preventDefault();$("dec").click()}});
$("exBtn").addEventListener("click",function(e){e.stopPropagation();pop($("exBtn"),$("exPop"))});
$("exPaste").addEventListener("click",function(){closePops();showInput("");$("code").focus()});
$("crRuns").addEventListener("click",function(e){e.preventDefault();showInput("")});
$("shBtn").addEventListener("click",function(e){e.stopPropagation();if(S.d){fillShare();pop($("shBtn"),$("shPop"))}});
$("kbBtn").addEventListener("click",function(e){e.stopPropagation();pop($("kbBtn"),$("kbPop"))});
$("shCopy").addEventListener("click",function(){copyText($("shUrl").value,"Link copied",$("shCopy"))});
$("shUrl").addEventListener("focus",function(){this.select()});
$("shStage").addEventListener("click",function(){copyText(shareUrl(true),"Link to "+S.st[S.i].t+" copied");closePops()});
$("shCode").addEventListener("click",function(){copyText(S.code,"Share code copied");closePops()});
$("shNative").addEventListener("click",function(){var d=S.d;navigator.share({title:"FirstRun: "+(d.title||d.target),text:verdictLine(d),url:shareUrl(false)}).catch(function(){});closePops()});
$("shX").addEventListener("click",function(){closePops()});$("shIn").addEventListener("click",function(){closePops()});
$("dlBtn").addEventListener("click",function(e){e.stopPropagation();pop($("dlBtn"),$("dlPop"))});
$("dlRep").addEventListener("click",function(){download("firstrun-"+slug(S.d)+"-report.md",reportMd(S.d),"text/markdown");closePops()});
$("dlPatch").addEventListener("click",function(){download("patch.diff",S.d.diff,"text/x-diff");closePops()});
$("dlPr").addEventListener("click",function(){download("pr_body.md",S.d.pr_body,"text/markdown");closePops()});
$("dlJson").addEventListener("click",function(){download("firstrun-"+slug(S.d)+".json",JSON.stringify(S.d,null,2),"application/json");closePops()});
$("tWalk").addEventListener("click",function(){if(S.mode!=="walk")setMode("walk")});
$("tRep").addEventListener("click",function(){if(S.mode!=="report")setMode("report")});
$("pgPrev").addEventListener("click",function(){go(S.i-1,true)});
$("pgNext").addEventListener("click",function(){go(S.i+1,true)});
$("cpc").addEventListener("click",function(){copyText($("runt").textContent,"Command copied",$("cpc"))});

document.addEventListener("keydown",function(e){
  if(e.key==="Escape"){if(OPEN){closePops(true);e.preventDefault()}return}
  var t=e.target,tag=t&&t.tagName;if(tag==="TEXTAREA"||tag==="INPUT"||tag==="SELECT"||(t&&t.isContentEditable))return;
  if(e.ctrlKey||e.metaKey||e.altKey)return;
  if(e.key==="?"){e.preventDefault();pop($("kbBtn"),$("kbPop"));return}
  if(OPEN&&/^Arrow(Up|Down)$/.test(e.key)){var it=[].slice.call(OPEN.p.querySelectorAll(".mi:not(.hide),input")),k=it.indexOf(document.activeElement);if(it.length){e.preventDefault();it[(k+(e.key==="ArrowDown"?1:-1)+it.length)%it.length].focus()}return}
  if(!S.d||!S.st.length)return;
  if(e.key==="ArrowRight"||e.key==="l"){e.preventDefault();go(S.i+1,S.mode==="walk"?"key":true)}
  else if(e.key==="ArrowLeft"||e.key==="h"){e.preventDefault();go(S.i-1,S.mode==="walk"?"key":true)}
  else if(e.key==="v"){setMode(S.mode==="walk"?"report":"walk")}
  else if(e.key==="s"){e.preventDefault();fillShare();pop($("shBtn"),$("shPop"))}
  else if(e.key==="j"||e.key==="k"){
    if(S.st[S.i].id!=="run")go2("run");
    var cur=ROWS.findIndex(function(r){return r.h===document.activeElement}),nx=cur<0?0:cur+(e.key==="j"?1:-1);nx=Math.max(0,Math.min(ROWS.length-1,nx));
    if(ROWS[nx]){e.preventDefault();ROWS[nx].h.focus();ROWS[nx].li.scrollIntoView({block:"nearest",behavior:RM?"auto":"smooth"})}
  }
  else if(e.key==="o"){var r=ROWS.find(function(x){return x.h===document.activeElement});if(r){e.preventDefault();setOpen(r,r.h.getAttribute("aria-expanded")!=="true")}}
});

fromHash();
})();
</script>
</body>
