.mm-test .sn-hero{background:var(--sn-test-bg)}.mm-audit .sn-hero{background:var(--sn-audit-bg)}
.sn-hero .sn-tile{width:40px;height:40px;border-radius:11px}.sn-hero .sn-tile svg{width:22px;height:22px}
