rre(r'/\* examples \*/.*?/\* wiring \*/', r'''/* the run list: one row per docs page, best result first */
function exIcon(st){return st==="verified"||st==="passed"?ic("ok","s-ok"):st==="failed"?ic("bad","s-bad"):ic("warn","s-warn")}
function openEx(name){if(location.search)history.replaceState(null,"",location.pathname+location.hash);DEEP=0;location.hash="ex="+name}
function pageKey(u){return String(u||"").replace(/^https?:\/\/(www\.)?/,"").replace(/[#?].*$/,"").replace(/\/+$/,"").toLowerCase()}
var RUNS=[],GROUP={},PAGES=[],F=(new URLSearchParams(location.search).get("f")||"all").replace(/[^a-z]/g,"");
var RANK={fixed:3,works:2,open:1};
function when(ts){var d=new Date(ts);return isNaN(d)?"":d.toLocaleString(undefined,{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}
function grouped(){
  GROUP={};
  RUNS.forEach(function(r){r.v=verdictOf(r.status,r.fixes);var k=pageKey(r.url||r.target);(GROUP[k]=GROUP[k]||{key:k,runs:[]}).runs.push(r)});
  PAGES=Object.keys(GROUP).map(function(k){var g=GROUP[k];g.runs.sort(function(a,b){return RANK[b.v]-RANK[a.v]||String(b.ts).localeCompare(String(a.ts))});g.best=g.runs[0];g.v=g.best.v;g.ts=g.runs.reduce(function(m,r){return r.ts>m?r.ts:m},"");return g});
  PAGES.sort(function(a,b){return RANK[b.v]-RANK[a.v]||String(b.ts).localeCompare(String(a.ts))});
}
function paintList(){
  if(!RUNS.length)return;
  var q=$("q").value.trim().toLowerCase(),fx=$("fx").checked,L=$("rl"),n=0,c={fixed:0,works:0,open:0};
  var vis=PAGES.filter(function(g){return fx||!g.best.fixture});
  vis.forEach(function(g){c[g.v]++});
  var T=$("tally");T.textContent="";
  [["all",c.fixed+c.works,"proven results"],["fixed",c.fixed,"fixes proven"],["works",c.works,"docs that work"],["open",c.open,"inconclusive"]].forEach(function(x){
    var b=el("button","k-"+x[0]);b.type="button";b.setAttribute("aria-pressed",F===x[0]?"true":"false");b.appendChild(el("b",null,String(x[1])));b.appendChild(document.createTextNode(x[2]));
    b.addEventListener("click",function(){F=x[0];history.replaceState(null,"",location.pathname+(F!=="all"?"?f="+F:""));paintList()});T.appendChild(b);
  });
  show("opennote",F==="open");
  L.textContent="";
  vis.forEach(function(g){
    var r=g.best;
    if(F==="all"?g.v==="open":g.v!==F)return;
    if(q&&g.runs.map(function(x){return x.title+" "+x.target+" "+x.summary+" "+x.url}).join(" ").toLowerCase().indexOf(q)<0)return;
    n++;
    var li=el("li"),a=el("a","rr");a.href="#ex="+encodeURIComponent(r.id);
    var b=el("span","badge vb "+VC[g.v]);b.appendChild(el("span","dot"));b.appendChild(document.createTextNode(VL[g.v]));a.appendChild(b);
    var t=el("span","rt",r.title);t.appendChild(el("small",null,r.target));a.appendChild(t);
    a.appendChild(el("span","rgo",g.v==="open"?"Open":"Replay"));
    a.appendChild(el("span","rs",g.v==="open"?String(r.summary||"").replace(/broke:/,"stopped:"):r.summary));
    var m=el("span","rm"),sp=el("span");sp.appendChild(el("b",null,r.passed+" of "+r.runnable));sp.appendChild(document.createTextNode(" steps passed"));m.appendChild(sp);
    if(r.fixes)m.appendChild(el("span",null,plural(r.fixes,"fix","fixes")));
    if(r.cost>0)m.appendChild(el("span",null,"$"+(+r.cost).toFixed(3)+" model cost"));
    m.appendChild(el("span",null,when(r.ts)));
    if(g.runs.length>1)m.appendChild(el("span",null,plural(g.runs.length-1,"other run")));
    if(r.fixture)m.appendChild(el("span","tagf","fixture"));
    a.appendChild(m);li.appendChild(a);L.appendChild(li);
  });
  show("none",n===0);
}
fetch("../runs/index.json").then(function(r){return r.json()}).then(function(j){RUNS=(j&&Array.isArray(j.runs)?j.runs:[]);grouped();paintList();if(S.d)renderVerdict(S.d)}).catch(function(){$("none").textContent="The run log did not load.";show("none",true)});
fetch("../examples/index.json").then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(j){
  (j&&Array.isArray(j.runs)?j.runs:[]).forEach(function(r){if(r&&r.summary)SUM[r.example]=String(r.summary)});if(S.d)renderVerdict(S.d);
}).catch(function(){});
$("q").addEventListener("input",paintList);$("fx").addEventListener("change",paintList);

/* wiring */''')
