.fx2 div{border-radius:20px;padding:16px 18px}
.fx2 b{display:block;font-size:16px;letter-spacing:-.02em}
.fx2 span{font-size:14px;color:var(--muted)}
.pl-note{margin-top:12px;font-size:13px;color:var(--muted)}
@media(max-width:820px){.pj{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:520px){.pj,.fx2{grid-template-columns:minmax(0,1fr)}.pc2{padding:18px 14px 12px}}
